sparqlExamples.query:
SELECT ?g (COUNT(*) AS ?triples)
WHERE {
  GRAPH ?g {
    ?s ?p ?o
  }
}
GROUP BY ?g
ORDER BY DESC(?triples)

SELECT ?class (COUNT(?instance) AS ?count)
WHERE {
  ?instance a ?class
}
GROUP BY ?class
ORDER BY DESC(?count)

SELECT ?property (COUNT(*) AS ?count)
WHERE {
  ?subject ?property ?object
}
GROUP BY ?property
ORDER BY DESC(?count)
